n_collab_Service_ListRoomsPage.signature:
// ListRoomsPage 是分页会话列表的 wire 组装点（B374）：在全量扁平序上按
// cursor 定位、取 limit 条，返回信封。游标是不透明字符串，编解码见
// encodeRoomCursor/decodeRoomCursor；页裁剪只经 trimRoomPage 一处。
//
// Ticket 0：本条为直通镜像——调 listRooms 取全量后交 trimRoomPage，后者
// 本轮返回整表、hasMore=false。真裁剪归 implement（冻结清单 F5-F8）。
func (s *Service) ListRoomsPage(project, member, pageCursor string, limit int) (proto.RoomsPage, error) {
	rooms, err := s.listRooms(project, member)
	if err != nil {
		return proto.RoomsPage{}, err
	}
	page, next, hasMore, err := trimRoomPage(rooms, pageCursor, limit)
	if err != nil {
		return proto.RoomsPage{}, err
	}
	return proto.RoomsPage{Rooms: page, NextCursor: next, HasMore: hasMore}, nil
}

n_collab_trimRoomPage.signature:
// trimRoomPage 在扁平序上按游标切片（B374 页裁剪符号）。
//
// Ticket 0 为直通镜像：返回整表、next=""、hasMore=false，不实现真裁剪。
// implement 轮按契约 §3.2 填充：limit 收敛、ID 定位为主判据、
// (LastActivity,roomID) 为兜底比较、末条编 next。
func trimRoomPage(rooms []proto.RoomSummary, pageCursor string, limit int) ([]proto.RoomSummary, string, bool, error) {
	if _, _, err := decodeRoomCursor(pageCursor); err != nil {
		return nil, "", false, err
	}
	return rooms, "", false, nil
}

n_collab_encodeRoomCursor.signature:
// encodeRoomCursor 把 (LastActivity, roomID) 编码为不透明游标：
// base64url_nopad(json.Marshal({a,r}))。客户端不回解。
func encodeRoomCursor(lastActivity time.Time, roomID string) string {
	raw, err := json.Marshal(roomCursor{A: lastActivity.UnixNano(), R: roomID})
	if err != nil {

		return ""
	}
	return base64.RawURLEncoding.EncodeToString(raw)
}

n_collab_decodeRoomCursor.signature:
// decodeRoomCursor 解码游标；空串表示首页（零值，nil error）。非法 base64、
// 非法 JSON，或载荷缺 a/r 键 / 键类型不符（如 `{}`、`{"a":"x"}`）都返回裹了
// ErrInvalidCursor 的 error（gateway 据此映射 400，契约 §3.2 冻结清单 F4）。
func decodeRoomCursor(raw string) (time.Time, string, error) {
	if raw == "" {
		return time.Time{}, "", nil
	}
	decoded, err := base64.RawURLEncoding.DecodeString(raw)
	if err != nil {
		return time.Time{}, "", fmt.Errorf("%w: base64 解码: %v", ErrInvalidCursor, err)
	}
	// 用 map 而非直接 Unmarshal 进 roomCursor：后者对缺键/类型不符静默补零值，
	// 会把 `{}` 当合法游标（首条时间 + 空 ID），与 F4「缺键即非法」冲突。
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(decoded, &fields); err != nil {
		return time.Time{}, "", fmt.Errorf("%w: JSON 解码: %v", ErrInvalidCursor, err)
	}
	var payload roomCursor
	rawA, okA := fields["a"]
	if err := json.Unmarshal(rawA, &payload.A); !okA || err != nil {
		return time.Time{}, "", fmt.Errorf("%w: 缺键或类型不符 a", ErrInvalidCursor)
	}
	rawR, okR := fields["r"]
	if err := json.Unmarshal(rawR, &payload.R); !okR || err != nil {
		return time.Time{}, "", fmt.Errorf("%w: 缺键或类型不符 r", ErrInvalidCursor)
	}
	return time.Unix(0, payload.A).UTC(), payload.R, nil
}

m_collab_roomCursor.signature:
type roomCursor struct {
	A	int64	`json:"a"`
	R	string	`json:"r"`
}

n_agentd_parseRoomsListParams.signature:
// parseRoomsListParams 解析分页 query（B374）。
//
// Ticket 0 为直通镜像：恒返回默认参数、Legacy=false，不解析请求；真解析
// （limit 收敛、非整数 400）归 implement（冻结清单 F2/F4）。
//
// 欠账可达性：在真解析落地前，F3 的 legacy 426、F2/F4 里由 query 输入的 HTTP
// 路径（非法 limit → 400）都**不可达**——本函数不读 *http.Request，Legacy 恒
// false、Cursor 恒空。当前唯一可达的 400 来自 ListRoomsPage 回传的非法游标
// （collab.ErrInvalidCursor），但那需要调用方显式带 cursor，而本函数还不搬
// query，故经 GET /api/rooms 亦不可达；该路径由 service 层测试锁定。
func parseRoomsListParams(_ *http.Request) (roomsListParams, error) {
	return roomsListParams{Limit: roomsListDefaultLimit}, nil
}

m_agentd_roomsListParams.signature:
type roomsListParams struct {
	Limit	int
	Cursor	string
	Legacy	bool
}

n_agentd_roomsListErrorStatus.signature:
// roomsListErrorStatus 把 ListRoomsPage 的错误映射为 HTTP 状态（契约冻结清单
// F4）：游标非法（collab.ErrInvalidCursor 经 decodeRoomCursor 裹出）→ 400；
// 其余（读卡/读事件/游标快照等列表组装失败）→ 500。单独成函数是为了让这条
// 映射能被一支只测映射、不依赖 HTTP 装配的测试钉住（Ticket 0 parseRoomsListParams
// 仍是空壳，游标不经 query 进入，400 分支在 handler 上暂不可达）。
func roomsListErrorStatus(err error) int {
	if errors.Is(err, collab.ErrInvalidCursor) {
		return http.StatusBadRequest
	}
	return http.StatusInternalServerError
}

n_agentd_Server_handleRoomsList.signature:
// handleRoomsList GET /api/rooms?project=&limit=&cursor= → ListRoomsPage
// （扁平活动排序分页列表，B374）。
//
// 错误映射（契约冻结清单 F4）：游标非法（collab.ErrInvalidCursor）→ 400；
// ListRoomsPage 的其它失败（读卡/读事件/游标快照）→ 500。Ticket 0 只落这条
// 可识别错误映射，真解析与 legacy 426 分支仍归 implement。
//
// 注意：本函数当前仍把 attach 投影与后台刷新交给 enrichRoomAttachments，后者
// 本轮仍是全量 AllTaskLinks + 全量远端 fan-out——刷新限域（F9/F10）尚未实现，
// 归 implement 轮。不得据本注释认为限域已生效。
func (s *Server) handleRoomsList(w http.ResponseWriter, r *http.Request) {
	project := r.URL.Query().Get("project")
	member := s.roomUserActor(r)
	params, err := parseRoomsListParams(r)
	if err != nil {
		s.log.Warn("会话列表分页参数无效", "project", project, "cause", err)
		writeErr(w, http.StatusBadRequest, err)
		return
	}
	page, err := s.rooms.ListRoomsPage(project, member, params.Cursor, params.Limit)
	if err != nil {
		if code := roomsListErrorStatus(err); code == http.StatusBadRequest {
			s.log.Warn("会话列表游标非法", "project", project, "cause", err)
			writeErr(w, code, err)
			return
		}
		s.log.Warn("会话列表读取失败", "project", project, "member", member, "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	s.enrichRoomAttachments(r.Context(), page.Rooms)
	s.log.Info("会话列表响应成功", "project", project, "member", member, "rooms", len(page.Rooms))
	writeJSON(w, http.StatusOK, page)
}
